import logging

HTTP_OK       = 200
HTTP_NOT_FOUND = 404

import os

HTTP_OK       = 200
HTTP_NOT_FOUND = 404

import httpx

logger = logging.getLogger(__name__)

LEDGER_SERVICE_URL = os.getenv(
    "LEDGER_SERVICE_URL",
    "http://ledger-service:8007",
).rstrip("/")


async def notify_authorization(
    payment_id: str,
    merchant_id: str,
    amount: int,
    currency: str = "usd",
) -> bool:
    try:
        async with httpx.AsyncClient(timeout=10.0) as client:
            response = await client.post(
                f"{LEDGER_SERVICE_URL}/record/authorization",
                json={
                    "payment_id": payment_id,
                    "merchant_id": merchant_id,
                    "amount": amount,
                    "currency": currency,
                },
            )
            return response.status_code == HTTP_OK
    except Exception as e: # noqa: BLE001
        logger.warning(f"Ledger authorization notification failed: {e}")
        return False


